<?php require_once __DIR__.'/../includes/bootstrap.php';if(customer_logged_in())redirect('/');$title='Customer Sign In';$errors=[];$next=$_GET['next']??($_POST['next']??'/');if(!str_starts_with($next,'/'))$next='/';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$login=trim($_POST['login']??'');$pass=$_POST['password']??'';$s=$pdo->prepare('SELECT * FROM customers WHERE (LOWER(email)=LOWER(?) OR username=?) AND status="ACTIVE" LIMIT 1');$s->execute([$login,$login]);$u=$s->fetch();if($u&&password_verify($pass,$u['password_hash'])){try{$pdo->prepare('UPDATE customers SET last_seen_at=NOW() WHERE customer_id=?')->execute([(int)$u['customer_id']]);}catch(Throwable $ignore){}$_SESSION['customer_id']=(int)$u['customer_id'];$_SESSION['customer']=['id'=>(int)$u['customer_id'],'name'=>$u['full_name'],'email'=>$u['email'],'username'=>$u['username'],'phone'=>$u['phone']];$_SESSION['flash']=['type'=>'success','msg'=>'Welcome back, '.$u['full_name'].'.'];redirect($next);}$errors[]='Invalid customer sign-in details.';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><link rel="stylesheet" href="/assets/style.css?v=22"><style><?=file_get_contents(__DIR__.'/../assets/style.css')?></style></head><body class="auth-body"><script>function shadrilGoBack(){try{if(document.referrer){var u=new URL(document.referrer,location.href);if(u.origin===location.origin){history.back();return false;}}}catch(e){}location.href="/";return false;}</script><div class="auth-wrap"><a class="brand auth-brand" href="/">Shadril Shopping Store</a><div class="auth-page-back"><?=back_button('Previous page')?></div><div class="auth-card"><div class="auth-copy"><span class="eyebrow">WELCOME BACK</span><h1>Sign in to shop</h1><p>After signing in, shopping controls appear automatically on every product.</p></div><?php if($errors): ?><div class="errors"><?=e($errors[0])?></div><?php endif; ?><form method="post" class="form"><?=csrf_field()?><input type="hidden" name="next" value="<?=e($next)?>"><label>Email or username<input name="login" required autofocus></label><label>Password<input type="password" name="password" required></label><div class="forgot-row"><a href="/auth/forgot-password.php">Forgot password?</a></div><button class="btn primary full">Sign in</button></form><a class="btn home-return full" href="/">Return to homepage</a><div class="auth-divider"><span>OR</span></div><a class="google-btn" href="/auth/google-start.php">G&nbsp;&nbsp; Continue with Google</a><p class="auth-links">New customer? <a href="/auth/register.php">Sign up</a></p><a class="management" href="/auth/login.php">Management access</a></div></div></body></html>
